options.getOption:
const dataSeries = (typeof context !== 'undefined' && context?.panel?.data?.series) 
  ? context.panel.data.series 
  : ((typeof data !== 'undefined' && data?.series) ? data.series : []);

const seriesMap = {};
dataSeries.forEach(s => {
  if (s && s.refId) seriesMap[s.refId] = s;
});

const readFrame = (refId) => {
  const frame = seriesMap[refId];
  if (!frame || !frame.fields) return [];
  const len = frame.length !== undefined ? frame.length : (frame.fields[0]?.values?.length ?? 0);
  const rows = [];
  for (let i = 0; i < len; i++) {
    const obj = {};
    frame.fields.forEach(f => {
      obj[f.name] = Array.isArray(f.values) ? f.values[i] : (f.values?.get ? f.values.get(i) : f.values?.[i]);
    });
    rows.push(obj);
  }
  return rows;
};

const getVal = (r) => {
  if (r.Value !== undefined && r.Value !== null) return Number(r.Value) || 0;
  for (const k in r) {
    if (k.startsWith('Value') && r[k] !== undefined && r[k] !== null) return Number(r[k]) || 0;
  }
  return 0;
};

const fmtBytes = (bps) => {
  const v = Number(bps) || 0;
  if (v >= 1073741824) return (v / 1073741824).toFixed(2) + ' GB/s';
  if (v >= 1048576) return (v / 1048576).toFixed(2) + ' MB/s';
  if (v >= 1024) return (v / 1024).toFixed(1) + ' KB/s';
  return v.toFixed(0) + ' B/s';
};

const barHtml = (pct, color) => {
  const w = Math.min(100, Math.max(0, Number(pct) || 0));
  return `<div style="width:100%;height:6px;background:rgba(148,163,184,0.2);border-radius:3px;overflow:hidden;margin-top:3px;">
    <div style="width:${w}%;height:100%;background:${color};border-radius:3px;"></div>
  </div>`;
};

// 1. 聚合节点状态与硬件详情
const nodesMap = {};
readFrame('N_INFO').forEach(r => {
  const id = r.id || r.host || r.instance;
  if (!id) return;
  nodesMap[id] = {
    id: id,
    ip: r.subTitle || r.dn42_ip || 'N/A',
    cpuModel: r.cpu_model || 'Unknown CPU',
    memTotal: r.mem_total_gib || '0',
    diskTotal: r.disk_total_gib || '0',
    up: 0, cpu: 0, memPct: 0, memUsed: 0, diskPct: 0, diskUsed: 0, rx: 0, tx: 0,
    role: r.role || '',
    isController: String(r.is_controller) === 'true' || String(r.role) === 'border'
  };
});

const bindMetric = (refId, key) => {
  readFrame(refId).forEach(r => {
    const id = r.id || r.host || r.instance;
    if (id && nodesMap[id]) {
      nodesMap[id][key] = getVal(r);
    }
  });
};

bindMetric('N_UP', 'up');
bindMetric('N_CPU', 'cpu');
bindMetric('N_MEM', 'memPct');
bindMetric('N_MEM_USED', 'memUsed');
bindMetric('N_DISK', 'diskPct');
bindMetric('N_DISK_USED', 'diskUsed');
bindMetric('N_RX', 'rx');
bindMetric('N_TX', 'tx');

// 2. 聚合边（隧道连接）状态：将双向边合并展示，保留双向延迟、丢包与实时网速
const edgePairs = {};
readFrame('E_RTT').forEach(r => {
  if (!r.source || !r.target) return;
  [r.source, r.target].forEach(nid => {
    if (!nodesMap[nid]) {
      nodesMap[nid] = { id: nid, ip: 'DN42 Peer', cpuModel: 'Babel Neighbor', memTotal: '-', diskTotal: '-', up: 1, cpu: 0, memPct: 0, memUsed: 0, diskPct: 0, diskUsed: 0, rx: 0, tx: 0, role: '', isController: false, isPeer: true };
    }
  });
  const key = [r.source, r.target].sort().join('<->');
  if (!edgePairs[key]) {
    edgePairs[key] = { source: r.source, target: r.target, rtt: 0, loss: 0, speed: 0 };
  }
  edgePairs[key].rtt = getVal(r);
});

readFrame('E_LOSS').forEach(r => {
  if (!r.source || !r.target) return;
  const key = [r.source, r.target].sort().join('<->');
  if (edgePairs[key]) edgePairs[key].loss = Math.max(edgePairs[key].loss, getVal(r));
});

readFrame('E_SPEED').forEach(r => {
  if (!r.source || !r.target) return;
  const key = [r.source, r.target].sort().join('<->');
  if (edgePairs[key]) edgePairs[key].speed += getVal(r);
});

// 3. 构建 Material 扁平化节点与边数组
const graphNodes = Object.values(nodesMap).map(n => {
  const isUp = n.up >= 1;
  const isWarn = isUp && (n.cpu > 85 || n.memPct > 90);
  const isPeer = n.isPeer;
  const fill = !isUp ? '#EF4444' : (isPeer ? '#3B82F6' : (isWarn ? '#F59E0B' : '#10B981'));
  const ring = !isUp ? 'rgba(239,68,68,0.28)' : (isPeer ? 'rgba(59,130,246,0.28)' : (isWarn ? 'rgba(245,158,11,0.28)' : 'rgba(16,185,129,0.25)'));
  const isCtrl = n.isController;

  return {
    name: n.id,
    value: n.cpu,
    nodeData: n,
    symbolSize: isCtrl ? 54 : 44,
    itemStyle: {
      color: fill,
      borderColor: ring,
      borderWidth: isCtrl ? 10 : 7,
      shadowBlur: 14,
      shadowColor: ring
    },
    label: {
      show: true,
      position: 'inside',
      formatter: `{title|${n.id}}\n{sub|${isUp ? (n.cpu > 0 ? n.cpu.toFixed(0) + '%' : 'UP') : 'DOWN'}}`,
      rich: {
        title: { fontSize: 12, fontWeight: 700, color: '#FFFFFF', lineHeight: 15 },
        sub: { fontSize: 10, fontWeight: 500, color: 'rgba(255,255,255,0.9)', lineHeight: 13 }
      }
    }
  };
});

const graphLinks = Object.values(edgePairs).map(e => {
  const isBad = e.loss > 5 || e.rtt > 260;
  const isMid = !isBad && (e.loss > 0 || e.rtt > 120);
  const lineColor = isBad ? '#F43F5E' : (isMid ? '#38BDF8' : '#10B981');
  const width = Math.min(6, Math.max(1.8, 1.8 + Math.log10((e.speed || 1) / 1024 + 1)));

  return {
    source: e.source,
    target: e.target,
    edgeData: e,
    lineStyle: {
      color: lineColor,
      width: width,
      type: e.loss > 10 ? 'dashed' : 'solid',
      opacity: 0.85,
      curveness: 0.08
    },
    label: {
      show: true,
      formatter: `${e.rtt.toFixed(0)}ms` + (e.loss > 0 ? ` · ${e.loss.toFixed(0)}%` : '') + (e.speed > 10240 ? `\n${fmtBytes(e.speed)}` : ''),
      fontSize: 10,
      color: '#CBD5E1',
      backgroundColor: 'rgba(15,23,42,0.82)',
      padding: [3, 6],
      borderRadius: 4
    }
  };
});

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'item',
    backgroundColor: 'rgba(15, 23, 42, 0.94)',
    borderColor: 'rgba(148, 163, 184, 0.2)',
    borderWidth: 1,
    padding: 14,
    extraCssText: 'border-radius: 12px; box-shadow: 0 10px 25px -5px rgba(0,0,0,0.5); backdrop-filter: blur(8px);',
    formatter: (params) => {
      if (params.dataType === 'node') {
        const d = params.data.nodeData;
        const isUp = d.up >= 1;
        const badgeBg = isUp ? 'rgba(16,185,129,0.2)' : 'rgba(239,68,68,0.2)';
        const badgeFg = isUp ? '#34D399' : '#F87171';
        return `<div style="min-width:250px;font-family:Inter,system-ui,sans-serif;color:#F8FAFC;">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
            <span style="font-size:16px;font-weight:700;">${d.id}</span>
            <span style="background:${badgeBg};color:${badgeFg};padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600;">
              ${isUp ? '● ONLINE' : '● OFFLINE'}
            </span>
          </div>
          <div style="font-size:12px;color:#94A3B8;margin-bottom:10px;">
            DN42 IP: <code style="color:#E2E8F0;">${d.ip}</code>
          </div>
          <div style="font-size:11px;color:#CBD5E1;background:rgba(30,41,59,0.7);padding:6px 8px;border-radius:6px;margin-bottom:10px;">
            ⚙️ ${d.cpuModel}
          </div>
          <div style="margin-bottom:8px;font-size:12px;">
            <div style="display:flex;justify-content:space-between;"><span>CPU 占用</span><b>${d.cpu.toFixed(1)}%</b></div>
            ${barHtml(d.cpu, d.cpu > 80 ? '#EF4444' : '#3B82F6')}
          </div>
          <div style="margin-bottom:8px;font-size:12px;">
            <div style="display:flex;justify-content:space-between;"><span>内存 (${d.memUsed.toFixed(1)} / ${d.memTotal} GiB)</span><b>${d.memPct.toFixed(1)}%</b></div>
            ${barHtml(d.memPct, d.memPct > 85 ? '#F59E0B' : '#10B981')}
          </div>
          <div style="margin-bottom:10px;font-size:12px;">
            <div style="display:flex;justify-content:space-between;"><span>磁盘 (${d.diskUsed.toFixed(1)} / ${d.diskTotal} GiB)</span><b>${d.diskPct.toFixed(1)}%</b></div>
            ${barHtml(d.diskPct, d.diskPct > 85 ? '#EF4444' : '#8B5CF6')}
          </div>
          <div style="display:flex;justify-content:space-between;font-size:12px;padding-top:8px;border-top:1px solid rgba(148,163,184,0.15);">
            <span style="color:#34D399;">↑ ${fmtBytes(d.tx)}</span>
            <span style="color:#38BDF8;">↓ ${fmtBytes(d.rx)}</span>
          </div>
        </div>`;
      } else if (params.dataType === 'edge') {
        const e = params.data.edgeData;
        return `<div style="min-width:200px;font-family:Inter,system-ui,sans-serif;color:#F8FAFC;">
          <div style="font-size:14px;font-weight:700;margin-bottom:8px;border-bottom:1px solid rgba(148,163,184,0.15);padding-bottom:6px;">
            🔗 ${e.source} ⇄ ${e.target}
          </div>
          <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px;">
            <span style="color:#94A3B8;">实时延迟 (RTT):</span><b>${e.rtt.toFixed(2)} ms</b>
          </div>
          <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px;">
            <span style="color:#94A3B8;">丢包率 (Loss):</span><b style="color:${e.loss > 0 ? '#F43F5E' : '#34D399'};">${e.loss.toFixed(1)}%</b>
          </div>
          <div style="display:flex;justify-content:space-between;font-size:12px;">
            <span style="color:#94A3B8;">实时吞吐 (Speed):</span><b style="color:#38BDF8;">${fmtBytes(e.speed)}</b>
          </div>
        </div>`;
      }
    }
  },
  series: [
    {
      type: 'graph',
      layout: 'force',
      roam: true,
      draggable: true,
      data: graphNodes,
      links: graphLinks,
      edgeSymbol: ['circle', 'arrow'],
      edgeSymbolSize: [4, 7],
      force: {
        repulsion: 1100,
        edgeLength: [130, 240],
        gravity: 0.08,
        layoutAnimation: true
      },
      emphasis: {
        focus: 'adjacency',
        lineStyle: { width: 5 }
      }
    }
  ]
};

targets.expr:
max by (id, source, target, device) (
  label_join(dn42_edge_rtt_ms or dn42_babel_link_rtt_ms, "id", "->", "source", "target")
)

max by (id) (
  label_replace(dn42_node_cpu_usage_percent, "id", "$1", "instance", "(.*)")
)
or
round(max by (id) (
  label_replace(
    100 * sum by (instance) (rate(node_cpu_seconds_total{mode=~"user|nice|system|irq|softirq"}[1m])) / sum by (instance) (rate(node_cpu_seconds_total{mode=~"user|nice|system|idle|iowait|irq|softirq|steal"}[1m])),
    "id", "$1", "instance", "(.*)"
  )
), 0.1)

max by (id) (
  label_replace(dn42_node_mem_usage_percent, "id", "$1", "instance", "(.*)")
)
or
round(max by (id) (
  label_replace(
    ((node_memory_MemTotal_bytes - node_memory_MemAvailable_bytes) / node_memory_MemTotal_bytes) * 100,
    "id", "$1", "instance", "(.*)"
  )
), 0.1)

max by (id) (
  label_replace(dn42_node_disk_usage_percent, "id", "$1", "instance", "(.*)")
)
or
round(max by (id) (
  label_replace(
    ((node_filesystem_size_bytes{mountpoint="/"} - node_filesystem_free_bytes{mountpoint="/"}) / node_filesystem_size_bytes{mountpoint="/"}) * 100,
    "id", "$1", "instance", "(.*)"
  )
), 0.1)

count by (id) (
  label_replace(dn42_babel_link_up == 1, "id", "$1", "source", "(.*)")
)
or (0 * max by (id) (
  label_replace(up{job="node"}, "id", "$1", "instance", "(.*)")
))
